    row0 = grid[0]
    bg = row0[0]

    # Find special rows (rows that are different from the "middle" rows)
    # A special row has values that match the border pattern
    special_rows = []
    for i, row in enumerate(grid):
        if len(set(row)) <= 2 and grid[i][0] not in [5, 9]:
            special_rows.append(i)

    # If no special rows detected, use all rows
    if not special_rows:
        # Try to detect by looking for rows with 2 or fewer unique values
        for i, row in enumerate(grid):
            if len(set(row)) <= 2:
                if len(set(row for r in grid if r[i] == grid[0][i])) == 1:
                    special_rows.append(i)

    if not special_rows:
        special_rows = [0]

    # Get all non-bg marker values and their columns
    all_marker_cols = {}
    for row_idx in special_rows:
        row = grid[row_idx]
        marker_cols = {}
        for c, v in enumerate(row):
            if v != bg:
                marker_cols[v] = marker_cols.get(v, 0) + 1
        for v, count in marker_cols.items():
            marker_cols[v] = count

    # Find the marker value that appears most frequently or in all rows
    if not marker_cols:
        return [[bg]]

    # Get columns for the dominant marker value (one that appears in all special rows)
    dominant_marker_val = None
    for v, _ in marker_cols.items():
        all_rows_with_v = sum(1 for i in special_rows if grid[i][c] == v)

    # Actually just use the most frequent marker value
    dominant_val = max(marker_cols.keys(), key=lambda k: marker_cols[k])

    # Get its columns across all special rows
    all_dom_cols = set()
    for row_idx in special_rows:
        row = grid[row_idx]
        for c in range(len(row)):
            if row[c] == dominant_val:
                all_dom_cols.add(c)

    all_dom_cols = sorted(all_dom_cols)
    num_regions = len(all_dom_cols) - 1 if len(all_dom_cols) >= 2 else 0

    result = [[dominant_val] * num_regions] if num_regions >= 1 else [[bg]]
    return result

